<template><div class="app-container" v-loading="loading"><div class="heading"><div><h2>门户工作台</h2><p>先保存草稿，再预览与发布。多人协作规则由管理员在“协作设置”中明确开启。</p></div><el-button @click="load">刷新工作台</el-button></div><div class="shortcuts"><el-button v-if="can('cms:article:add')&&can('cms:article:list')" type="primary" @click="go('/cms/article')">文章管理</el-button><el-button v-if="can('cms:product:list')" @click="go('/cms/product')">产品展示</el-button><el-button v-if="can('cms:page:list')" @click="go('/cms/page')">单页管理</el-button><el-button v-if="can('cms:asset:list')" @click="go('/cms/asset')">素材库</el-button><el-button @click="portal">查看门户</el-button><el-button v-if="can('cms:workflow:list')" @click="go('/cms/workflow')">协作设置</el-button></div>
<div class="cards" v-if="data"><el-card><p>我的正式草稿</p><strong>{{data.ownDrafts}}</strong><small>只统计我保存的新版本；历史稿件不猜测作者。</small></el-card><el-card v-if="reviewActive&&can('cms:review:list')" @click="go('/cms/review')"><p>待我审核</p><strong>{{data.pendingReview}}</strong><small>我提交：{{data.submitted}} 待审 · {{data.approved}} 待发布 · {{data.rejected}} 退回</small></el-card><el-card v-if="data.inquiryVisible" @click="go('/cms/inquiry')"><p>当前范围待处理询盘</p><strong>{{data.inquiryNew}}</strong><small>今日跟进 {{data.inquiryToday}} · 已逾期 {{data.inquiryOverdue}}</small></el-card><el-card><p>我的定时任务失败</p><strong>{{data.failedSchedules}}</strong><small>检查下方失败原因，修正后重新安排。</small></el-card></div>
<el-divider>我的正式草稿</el-divider><el-table :data="drafts"><el-table-column prop="contentId" label="编号" width="90"/><el-table-column prop="title" label="标题"/><el-table-column label="模块" width="110"><template #default="s">{{kindLabels[s.row.kind]}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="s"><el-button link type="primary" @click="go({path:'/cms/'+s.row.kind.toLowerCase(),query:{contentId:s.row.contentId}})">打开工作稿</el-button></template></el-table-column></el-table><pagination v-if="draftTotal" :total="draftTotal" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="loadDrafts"/>
<el-divider v-if="data?.failedSchedules">我的失败任务</el-divider><el-table v-if="data?.failedSchedules" :data="schedules"><el-table-column prop="scheduleId" label="任务" width="90"/><el-table-column prop="resultMessage" label="失败原因"/><el-table-column prop="dueAt" label="原执行时间" width="170"/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="go({path:'/cms/'+s.row.kind.toLowerCase(),query:{scheduleContentId:s.row.contentId}})">检查并重新安排</el-button></template></el-table-column></el-table><pagination v-if="scheduleTotal" :total="scheduleTotal" v-model:page="spg.pageNum" v-model:limit="spg.pageSize" @pagination="loadSchedules"/>
<template v-if="data?.analyticsVisible"><el-divider>近7天访问趋势</el-divider><el-alert v-if="!data.analyticsEnabled" title="访问统计未开启；到站点与外观中保存并发布统计设置后才开始记录。" :closable="false"/><el-table v-else :data="data.visits"><el-table-column prop="value" label="日期"/><el-table-column prop="hits" label="访问次数"/></el-table><p v-if="data.analyticsEnabled&&!data.visits.length">暂无访问数据。</p><el-button link @click="go('/cms/statistics')">查看完整统计</el-button></template></div></template>
<script setup>
import{ref,reactive,onMounted,onBeforeUnmount,onDeactivated,onActivated}from'vue';import{useRouter}from'vue-router';import{workflow,kindLabels}from'@/api/cms/workflow';import auth from '@/plugins/auth';const router=useRouter(),can=p=>auth.hasPermi(p),data=ref(),drafts=ref([]),draftTotal=ref(0),schedules=ref([]),scheduleTotal=ref(0),reviewActive=ref(false),loading=ref(false),pg=reactive({pageNum:1,pageSize:10}),spg=reactive({pageNum:1,pageSize:10});let epoch=0
const go=p=>router.push(p);function portal(){window.open('/','_blank','noopener,noreferrer')}
async function load(){const n=++epoch;loading.value=true;try{const [r,o]=await Promise.all([workflow('workbench'),workflow('workflow/options')]);if(n!==epoch)return;data.value=r.data;reviewActive.value=o.data.policies.some(p=>p.required);await Promise.all([loadDrafts(),loadSchedules()])}finally{if(n===epoch)loading.value=false}}
async function loadDrafts(){const n=epoch,r=await workflow('workbench/drafts','get',undefined,{...pg});if(n===epoch){drafts.value=r.rows;draftTotal.value=r.total}}async function loadSchedules(){const n=epoch,r=await workflow('workbench/schedules','get',undefined,{...spg});if(n===epoch){schedules.value=r.rows;scheduleTotal.value=r.total}}
function close(){++epoch;data.value=null;drafts.value=[];schedules.value=[]}onMounted(load);onBeforeUnmount(close);let resumed=false;onDeactivated(()=>{resumed=true;close()});onActivated(()=>{if(resumed){resumed=false;load()}})
</script><style scoped>.heading{display:flex;justify-content:space-between;gap:16px;align-items:center}.heading h2{margin-top:0}.heading p,.cards p{color:var(--el-text-color-secondary)}.shortcuts{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.shortcuts .el-button{margin-left:0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.cards strong{font-size:30px}.cards small{display:block;margin-top:12px;color:var(--el-text-color-secondary)}</style>
